#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBknDbEngine: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = BknDbEngine

    public static func lift(_ handle: UInt64) throws -> BknDbEngine {
        return BknDbEngine(unsafeFromHandle: handle)
    }

    public static func lower(_ value: BknDbEngine) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BknDbEngine {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: BknDbEngine, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


