    )
    case DatabaseLocked(path: String
    )
    case DuplicateKey(table: String, key: String
    )
    case SchemaMismatch(table: String, message: String
    )
    case ConstraintViolation(table: String, message: String
    )
    case Corruption(message: String
    )
    case InvalidQuery(message: String
    )
    case DatabaseClosed
    case TransactionInProgress
    case TransactionClosed
    case TransactionAborted(message: String
    )
    case InvalidArgument(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

