public struct FfiConverterTypeFfiBknError: FfiConverterRustBuffer {
    typealias SwiftType = FfiBknError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiBknError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Backend(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .TableNotFound(
            table: try FfiConverterString.read(from: &buf)
            )
        case 3: return .NotFound
        case 4: return .Encoding(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .ReservedTableName(
            table: try FfiConverterString.read(from: &buf)
            )
        case 6: return .DatabaseLocked(
            path: try FfiConverterString.read(from: &buf)
            )
        case 7: return .DuplicateKey(
            table: try FfiConverterString.read(from: &buf), 
            key: try FfiConverterString.read(from: &buf)
            )
        case 8: return .SchemaMismatch(
            table: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 9: return .ConstraintViolation(
            table: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 10: return .Corruption(
            message: try FfiConverterString.read(from: &buf)
            )
        case 11: return .InvalidQuery(
            message: try FfiConverterString.read(from: &buf)
            )
        case 12: return .DatabaseClosed
        case 13: return .TransactionInProgress
        case 14: return .TransactionClosed
        case 15: return .TransactionAborted(
            message: try FfiConverterString.read(from: &buf)
            )
        case 16: return .InvalidArgument(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiBknError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Backend(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .TableNotFound(table):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(table, into: &buf)
            
        
        case .NotFound:
            writeInt(&buf, Int32(3))
        
        
        case let .Encoding(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .ReservedTableName(table):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(table, into: &buf)
            
        
        case let .DatabaseLocked(path):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .DuplicateKey(table,key):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(table, into: &buf)
            FfiConverterString.write(key, into: &buf)
            
        
        case let .SchemaMismatch(table,message):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(table, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .ConstraintViolation(table,message):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(table, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Corruption(message):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidQuery(message):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(message, into: &buf)
            
        
        case .DatabaseClosed:
            writeInt(&buf, Int32(12))
        
        
        case .TransactionInProgress:
            writeInt(&buf, Int32(13))
        
        
        case .TransactionClosed:
            writeInt(&buf, Int32(14))
        
        
        case let .TransactionAborted(message):
            writeInt(&buf, Int32(15))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidArgument(message):
            writeInt(&buf, Int32(16))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


